"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Başlangıç / bitiş mesafesi flanşı kısmi flanşa dönüştürür. Eskizdeki diğer kapalı profiller plakada kesiklere dönüşür. Flanştaki delikler ve pencereler: kenar boyunca merkez (eğri kenarda yay boyunca), büküm sonundan itibaren merkez, boyut – bunlar açınımda da görünür. Eğri bir kenar, köşe oluşturmadan komşu kenarına geçiyorsa ve ikisinde de aynı büküm açısına sahip bir flanş varsa, flanşlar gevşetme kesiği olmadan birbirine geçer. „Eskizden kontur“, bir eskizin kapalı profillerini flanştan keser: X ekseni kenar boyunca, Y ekseni flanşın içine doğru uzanır, sıfır noktası kenar başlangıcında, büküm sonunda bulunur (kaydırılabilir).",
