"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Kaybolacak tüm yüzeyleri seçin (cepte duvarlar ve taban, delikte duvar, radyusta yuvarlatılmış yüzey). Komşu yüzeyler boşluk üzerinden uzatılır. Bu adım gövde değiştiğinde yeniden hesaplanır; ilk seferde bunun için büyük geometri çekirdeği yüklenir (birkaç saniye).",
