"Das Bild konnte nicht gelesen werden.":"Görüntü okunamadı.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Görüntü düzlemde şablon olarak duruyor. Boyut, konum, döndürme ve opaklığı ardından özellikler penceresinde ayarlayın (ör. genişliği bilinen bir ölçüye göre).",
