"Das Maß muss größer als 0 sein.":"Ölçü 0'dan büyük olmalıdır.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Ağ bir üçgen ağı olarak kalır (B-Rep değil). AĞ altında düzenleyin: Onar, Azalt, Yumuşat, Düzlem kesiti … İmalattaki 3D frezeleme stratejileri bunu doğrudan işleyebilir.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"Ağda {0} üçgen var. Her biri gövdenin bir yüzeyi olur – bu uzun sürer ve gövdeyi ağırlaştırır. Önce “Azalt” kullanmak genellikle daha iyidir.\n\nYine de dönüştürülsün mü?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"Ağ kapalı değil. Önce “Onar” işlemini çalıştırın – gövde için kapalı bir kabuk gerekir.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"Ağ Z'de {0} ile {1} mm, X'te {2} ile {3} mm, Y'de {4} ile {5} mm arasında uzanır. Bir doğrudan toleranstan az sapan noktalar atılır.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profil ekseni kesmemelidir. Eskizdeki açık bir çizgi eksen olarak kullanılabilir.",
"Das Profil mit den jetzigen Werten überschreiben":"Profili mevcut değerlerle değiştir",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profil, bir çizgi/çoklu çizgi boyunca sürülür. Profili en iyisi yolun başlangıcına dik çizin (ör. profil XZ’de, yol XY’de).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profil, eskiz düzleminden başlayarak kabartma veya çukur olarak işlenir.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Ham parça, seçilen gövdeyi saran kutudur (artı ofset).",
"Das Setup hat keine Operationen.":"Kurulumda operasyon yok.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Takım, merkezi kanal boyunca ilerleyen daireler çizerek frezeler. Hiçbir zaman tam genişlikte kesmeye girmez – bu büyük paso derinliklerine izin verir, freze ve iş milini korur. Frezenin çapı kanal genişliğinin yaklaşık 60 %'ı olmalıdır.",
"Das Werkzeug schneidet die Fläche nicht":"Araç yüzeyi kesmiyor",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Takım, belirtilen paylara ulaşana kadar seçilen yüzeylere doğru keser.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Takım bir matkap gibi dikey olarak dalar, sıra sıra, modele artı paso payına kadar. Kesme kuvveti iş mili boyunca etki eder: uzun takımlar, derin kovuklar ve az rijit tezgahlar için uygundur. Takım merkezden kesmelidir.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Takım, belirtilen güvenlik mesafelerini dikkate alarak bu yüzeylerden kaçınır (bağlama elemanları, mengene).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Takım, yakındaki yüzeyleri işlerken bu yüzeylerden kaçınır ve güvenlik mesafelerine uyar.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"İlk Esc yalnızca takımı veya seçimi iptal eder – fazladan bir Esc eskizi kapatmaz",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Bu bir delik değil (radyus veya pim) – lütfen bir deliğin iç duvarına tıklayın.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Bu bir delik (silindirik yüzey) değil – lütfen delik duvarına tıklayın.",
"Das ist keine WerkFab-Design-Datei.":"Bu bir WerkFab tema dosyası değil.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Bu eğik bir kenar değil – pah kenarının iki ucuna tıklayın.",
