"Deckkraft der Fenster":"Pencere opaklığı",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Çap sıfır veya negatif olurdu – mesafeyi küçültün",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Diş freze tam malzemenin içinde çalışır: Önce pimin etrafını frezeleyerek açın (pimin dışında diş derinliğine kadar 2D kontur).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Gövdenin bu düzlemde silueti yok.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Gövde, görüntüdeki üçgenlerle ağ olarak alınır. Gövdenin kendisi korunur; gövdede sonradan yapılan değişiklikler ağı değiştirmez.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Gövde dikey merkez ekseni etrafında taranır ve tutucu konturu (kesitler) olarak belge takım kitaplığına kaydedilir.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Görünümün etrafında döndüğü nokta (serbest yörüngede). „İmlecin altında“: dönmenin başladığı model noktası.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Yarıçap, seçilen her kenarın başından sonuna doğru eşit şekilde büyür. Hangi ucun başlangıç olduğunu kenar belirler – gerekirse değiştirin.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Bir yüzeyin kenarı kapalı bir zincirdir: “sürekli” ile yarıçap bir kez çevre boyunca değişir; bu seçenek olmadan her kenarda ayrı ayrı başlangıç yarıçapından bitiş yarıçapına geçer.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Kesim hiçbir gövdeye değmiyor – malzeme kaldırılmıyor.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Metin, programda bu noktada yorum olarak yer alır.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Birinci mesafe, daha çok yukarı (Z) bakan yüzeyde ölçülür; ikinci mesafe veya açı diğer yüzey için geçerlidir. “Tarafları değiştir” bunu tersine çevirir. Teğet bağlanan kenarlar da dahil edilir.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Seçilen gövde ham parçadır (örn. döküm veya dövme ham parça). Kendisi işlenmez.",
