"Die ersten zwei gewählten Kurven sind die Leitkurven; die Bahnen laufen quer von der einen zur anderen.":"Seçilen ilk iki eğri kılavuz eğrilerdir; yollar birinden diğerine enine uzanır.",
"Die fertige Bahn wird an den weiteren Stellen wiederholt (Maße ab Werkstück-Nullpunkt). Das Modell und das Rohteil müssen dort Material haben – die Simulation zeigt es.{0}":"Tamamlanan yol diğer konumlarda tekrarlanır (ölçüler iş parçası sıfır noktasından). Model ve ham parça orada malzemeye sahip olmalıdır – simülasyon bunu gösterir.{0}",
"Die gespiegelte Form berührt den Körper nicht – es entsteht ein loses Stück.":"Aynalanan şekil gövdeye temas etmiyor – ayrık bir parça oluşur.",
"Die gewählte ebene Fläche wird durch die Zielebene ersetzt: Der Körper wächst bis zu ihr oder wird bis zu ihr gekürzt, die Seitenwände laufen gerade weiter. Mit einer geneigten Konstruktionsebene wird die Fläche schräg.":"Seçilen düz yüzey hedef düzlemle değiştirilir: gövde ona kadar büyür veya ona kadar kısaltılır, yan duvarlar düz devam eder. Eğik bir yapı düzlemiyle yüzey eğimli olur.",
"Die gewählten Flächen bekommen eine Dicke entlang ihrer Normalen – auch gewölbte Flächen. Angrenzende Flächen werden zu einem Stück verbunden.":"Seçilen yüzeylere normalleri boyunca kalınlık verilir – kavisli yüzeylere de. Bitişik yüzeyler tek parça olarak birleştirilir.",
"Die gewählten Flächen werden entfernt, der Körper wird nach innen ausgehöhlt.":"Seçilen yüzeyler kaldırılır, gövde içeriden oyulur.",
