"Die zweite Komponente muss ein anderer Körper sein.":"İkinci bileşen farklı bir gövde olmalıdır.",
"Dies ist das erste Setup – es gibt kein vorheriges Rohteil. Bis dahin gilt die relative Quadergröße.":"Bu ilk kurulum – önceki ham parça yok. O zamana kadar göreli kutu boyutu geçerlidir.",
