"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Özel ölçüler ve notlar, sayfada fareyle sürüklenebilir (ölçü çizgisinin mesafesi, kılavuz çizginin açısı, açı yayının yarıçapı). İki köşeye tıklamak = uzunluk ölçüsü. Üst görünüşte bir daire kenarına tıklamak = çap (veya yarıçap). Açı: önce köşe, sonra her iki koldan birer köşe noktası. Pah: eğik kenarın iki ucu – örneğin 2×45° verir. Her ölçünün ardındaki metin kutusunda ±0,1, H7 veya 4× gibi bir ek yer alır.",
