"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Yuvarlak bir freze her iç köşede yarıçapını bırakır – köşeli bir karşı parça buna sığmaz. Boşaltma, her keskin iç köşede kısaca köşeye girip geri çıkar.{0}{1}",
