"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Önce hareket ettirilecek gövdedeki yüzeye, sonra diğer gövdedeki hedef yüzeye tıklayın. Gövde, birinci tıklama noktası ikincinin üzerine gelene ve yüzeyler birbirine oturana kadar döndürülür ve kaydırılır.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Önce hareket ettirilecek gövdedeki kenara, sonra diğer gövdedeki hedef kenara tıklayın. Düz kenarlar çakışır (orta nokta orta noktaya); dairesel kenarlarda – delik ve pim – eksenler aynı yöne getirilir ve merkez noktaları birleştirilir.",
