"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Önce bir eskiz veya yapı düzlemi seçin – Ctrl+8 daha sonra ona dik olarak bakar.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Önce TASARIM'da bir gövde oluşturun veya bir ağ (STL) ekleyin.",
