"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Eskizin hiçbir profile ait olmayan düz çizgileri (yardımcı çizgiler dahil). Bükme: çizgi bükme bölgesinin ortasıdır, eskiz orada kesim ölçüsüdür – plakanın en büyük parçası yerinde kalır, çizginin ötesindeki her şey flanşlarıyla birlikte döner. Çizgi plakanın tamamı boyunca geçerlidir. Nervür: çizgi boyunca bir kaburga, kesitte ve uçlarda yuvarlak; sac kalınlığını korur.",
