"Geschlossen (Gehrung)":"Kapalı (gönye)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Kapalı: iki komşu kenardaki flanşlar köşenin açıortayına kadar uzanır ve orada boşluğu açık bırakır. Köşe boşaltma, bükme bölgelerinin kesiştiği yerde bulunur – hem açınımda hem bükülmüş parçada. Eğri kenardaki bir flanş da gerçek bir köşede gönyeli kesilir (orada köşe boşaltma olmadan).",
"Geschlossene Kette {0}":"Kapalı zincir {0}",
"Geschlossene Profile begrenzen den Bereich.":"Kapalı profiller bölgeyi sınırlar.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Etkin eskizin kapalı profillerini renkle doldur",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Kapalı profiller düz yüzeylere dönüşür – ör. kapak ve taban; yüzeyleri sonradan bir gövdede birleştirmek için.",
"Geschnitten ab X":"Kesit başlangıcı X",
