"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"İçe aktarılan gövdelerin tasarım geçmişi yoktur, ancak düzenlenmeye (radyus, pah, kesme …) devam edilebilir ve CAM için kullanılabilir. “Y ekseni yukarıda” ile, Y’si yukarı bakan programlardan gelen modeller doğru konuma getirilir.",
