"J (relativ)":"J (göreli)",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Her eskizin ilk eğrisi – açık veya kapalı. Eğriler bir kabukla birleştirilir (kalınlığı olmayan yüzey).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Her levha için bir dosya. Yol, dış hattın yanında hurda içinde yarım kesim aralığı kadar (frezelemede yarım freze kadar) kaydırılarak ilerler; kesikler kendi parçalarının dış hattından önce gelir, her kontur hurdadan bir girişle başlar. Açma M3 ile (lazer: M3 S…), kapatma M5 ile, delme süresi G4 olarak verilir. Sıfır noktası levhanın sol alt köşesidir; frezelemede Z0 sac yüzeyidir. Programı kullanmadan önce makinede veya bir NC simülatöründe kontrol edin.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Her eksen ayrı ayrı: bir kenara, köşeye, yüzeye veya deliğe tıklayın. Ayarlanmayan eksenler ham parça noktasından alınır.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Her operasyon program sonunda alt program (LBL) olarak, CALL LBL ile çağrılır",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Eskizdeki her daire bir delik merkezidir. Delme işlemi eskiz normalinin tersi yönünde (malzemenin içine doğru) yapılır.",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Eskizdeki her daire merkez etrafında (eskiz koordinatlarında) döndürülerek tekrarlanır – bölüm dairesi yarıçapı kadar uzaktaki bir daire, delik çemberi oluşturur.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Eskizdeki her daire bir ızgaraya dönüşür: eskizin X ve Y yönündeki aralıkları (negatif de olabilir).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Şimdi ikinci koldan bir nokta seçin.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Şimdi her yönü bir kez sonuna kadar hareket ettirin: kaydırın, çekin, basın, eğin, çevirin (10 sn) …",
