"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Alın yüzeyindeki (dönme eksenine dik) bir eskizin eğrileri, Z boyunca tahrikli bir frezeyle (X ve C birlikte hareket eder; Fanuc: kutupsal enterpolasyon G12.1). Açık eğriler gidiş-dönüş frezelenir. Derinlik alın yüzeyinden.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Dönme eksenine paralel uzanan bir eskizin eğrileri çevreye sarılır ve eksene bakan tahrikli bir frezeyle frezelenir (Z ve C birlikte hareket eder; Fanuc: silindirik enterpolasyon G7.1). Eskiz düzlemi konturun bulunduğu açıyı belirler; eskizdeki yatay doğrular parça etrafında yaylara dönüşür. Derinlik dış çaptan.",
"Kurzbefehl":"Kısayol",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Kısa yollarda (aşağıda kalma mesafesine kadar) takım geri çekilme yüksekliğine çıkmak yerine aşağıda geçiş ilerlemesiyle hareket eder – çarpışma kontrolü olmadan, bu yüzden küçük tutun.",
