"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Kontrol noktalarıyla yarıçap verilen değerlerden geçer (konum, kenar uzunluğunun %’si olarak). Bunu büyük geometri çekirdeği hesaplar; ilk seferde yüklenmesi birkaç saniye sürer.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D prob ile talaş kaldırılamaz",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Bitmiş parçayla karşılaştır: yeşil = ölçüsünde, mavi = artık malzeme, kırmızı = çok derin",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Fareyi bir konturun yanına getirin (taraf yönü belirler) · Esc bitirir",
"Mit diesem Werkzeug kann nicht gefräst werden":"Bu takımla frezeleme yapılamaz",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Kılavuzla yalnızca „Kılavuz çekme“ çevrimini kullanın – bir delme çevrimi kılavuzu kırar",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Birden çok pasoyla diş derinliği, her biri yaklaşık eşit talaş alan adımlarla frezelenir – küçük diş frezelerini ve sert malzemeleri korur. Boş geçiş son yolu paso vermeden bir kez daha izler.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"NC programında „Delme çevrimleri“ seçiliyse kontrol çevrimleri çıkarılır (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), aksi halde açık hareketler yazılır.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"“Aslını koru” ile asıl ve ayna görüntüsü tek bir ağ olur; ayna düzlemindeki noktalar birleştirilir – böylece açık bir yarım, kapalı bir parçaya dönüşür.",
