"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Yalnızca daha büyük bir frezenin köşelerde bıraktığını işle.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Yalnızca daha büyük bir frezenin ulaşamadığı kontur bölgelerini izle (iç köşeler, dar yerler). Giriş/çıkış yayları, tutma köprüleri ve finiş paso olmadan; telafi bilgisayarda.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Yalnızca referans takımın ulaşamadığı yerlerde: düz bölgeler paralel, dik bölgeler su hattı olarak. Listeden bir takımla onun biçimi de hesaba katılır – örneğin bir köşe radyüslü frezenin kanallarda bıraktığı kısım.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Yalnızca düz yüzeyler eskiz düzlemi olarak kullanılabilir.",
"Nur ebene Flächen können extrudiert werden":"Yalnızca düzlemsel yüzeyler ekstrüzyonla çıkarılabilir",
"Nur ebene Flächen lassen sich ersetzen":"Yalnızca düzlemsel yüzeyler değiştirilebilir",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Yalnızca düzlemsel ve silindirik yüzeyler (delikler, pimler) ofsetlenebilir",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Yalnızca takıma doğru yukarı bakan düz yüzeyler (bu kurulumda yatay).",
