"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Dönme ekseni boyunca kanal (örn. kama kanalı), eksene bakan tahrikli bir frezeyle; ana iş mili parçayı C ekseni olarak tutar. Kanal genişliği = freze Ø. Başlangıç/bitiş Z model Z cinsinden; kanal alın yüzeyine kadar uzanıyorsa freze önden girer, aksi halde başlangıçta dalar. Derinlik dış çaptan.",
