"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Açık kenarlar kırmızı gösterilir. “Onar” delikleri kapatır.",
"Offene Linie in einer Skizze wählen":"Eskizde açık bir çizgi seçin",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Açık veya kapalı eğriler eskize dik yönde çekilir – sonuç bir yüzeydir (kalınlığı olmayan duvar). “Kalınlaştır” veya “Birleştir” ile bundan hacim elde edilir.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Açık veya kapalı eğriler eksen etrafında döndürülür – sonuç bir yüzeydir, hacim değil.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Özel tuş yoksa varsayılan „{0}“ geçerlidir.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"“Modellenmiş” seçilmezse diş yalnızca gösterilir (hızlı). Modellenmiş seçildiğinde diş profili gerçekten kesilir, ör. 3B baskı için. M8 için delik = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP tornalama",
"Okuma OSP-M Fräsen":"Okuma OSP-M frezeleme",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 orada makine koordinatlarına gitmez (G53 takım boyu düzeltmesini iptal eder) – güvenlik yüksekliğine geri çekme, XY referans hareketi çıktıya eklenmedi",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: yumuşatma işlevi çıktıya eklenmedi (G5.1 Fanuc'a aittir) – Hi-Cut/Super-NURBS'i makinede ayarlayın",
