"OpenCascade (alle Funktionen)":"OpenCascade (tüm işlevler)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: tüm işlevler. Rust çekirdeği (truck, deneysel): temel gövdeler, ekstrüzyon, döndürme, delik, çoğaltma, aynalama, taşıma, ölçekleme, birleştirme ve STEP dışa aktarma – diğer özellikler “henüz desteklenmiyor” olarak işaretlenir.",
