"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Kabartma {0}: {1} mm, 3 × sac kalınlığından yüksek – dik duvarla sac yırtılır.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Kabartma: kontur kesilmez, yükseklik kadar plakadan dışarı bastırılır. Havşa kabartma: yuvarlak bir deliğin kenarı 90°'lik bir koni biçiminde bastırılır – ince sacdaki havşa başlı vidalar için (− aşağı: vida yukarıdan).",
