"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Tornalama eksenine paralel yerleştirilmiş bir eskizin kapalı konturlarından çevre üzerinde cep (iç konturlar ada olarak kalır). Eskiz çapa sarılır; eksene bakan tahrikli bir parmak freze içten dışa doğru talaş kaldırır (Z ve C birlikte hareket eder; Fanuc: silindirik enterpolasyon G7.1). Freze, en içteki halka boyunca rampa ile dalar.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Alın yüzeyinde, bir eskizin kapalı konturlarından (iç konturlar ada olarak kalır) Z boyunca tahrikli parmak frezeyle cep. Boşaltma içten dışa yapılır; freze en içteki yol boyunca rampa ile dalar ve bir seviye içinde aşağıda kalır. X ve C birlikte hareket eder (Fanuc: kutupsal enterpolasyon G12.1). Derinlik alın yüzeyinden.",
