"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„İç içe yerleştir“, kesim parçalarını komşularının boşluklarına ve girintilerine ve onların kesiklerine yerleştirir (90° döndürmeden yalnızca 180° çevrilerek); mesafenin altına hiçbir zaman inilmez. İşaret olmadan çevreleyen dikdörtgenlerine göre sıralar halinde yerleşirler. „Eskiz + gövde“ ile sac kalınlığında düz gövdeler oluşur; bunlar imalatta 2D kontur ile kesilebilir.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"„İç/Dış“ için kapalı kontur gerekir – açık eğrileri „Eğri üzerinde“ ile frezeleyin",
